extern "C" int sprintf(char *, const char *, ...);
extern "C" char *strcpy(char *, const char *);
extern "C" int strcmp(const char *, const char *);
extern "C" void __assert(const char *, const char *, int);
#define assert(x) ((x) ? (void)0 : __assert(#x, __FILE__, __LINE__))
#define NUMBER_OF_REPLAYS 4

struct os_file { static bool file_exists(const char *); };
struct nglFileBuf { unsigned char *Buf; unsigned int Size; unsigned int UserData; };
class stringx { char data[8]; public: stringx(); ~stringx(); stringx &operator=(const char *); };
class os_developer_options { public: enum flags_t { FLAG_STASH_ONLY = 1 }; static os_developer_options *inst(); bool is_flagged(flags_t) const; void set_flag(flags_t, bool); };
struct KSWaterState { float data[17]; int stage; int perturb; float tail[3]; };
struct CareerData { int beach; char pad[184]; char name[32]; };
struct SurferData { char name[32]; char pad[620]; };
extern CareerData CareerDataArray[32];
extern SurferData SurferDataArray[];
struct KSReplay { int sfr; int bch; };
extern KSReplay ksreplay;
void KSReadFile(const char *, nglFileBuf *, unsigned int);
void KSReleaseFile(nglFileBuf *);
int random(int);

class FEMenu { public: virtual ~FEMenu(); };
class BeachFrontEnd : public FEMenu { public: void PickDemo(int); };
class GraphicalMenuSystem { public: enum Menu { TitleMenu, MainMenu, BeachMenu }; FEMenu **menus; Menu active; void PrepareToExit(); };
class game { public: void setHeroname(int, const stringx &); void SetSurferIdx(int, int); void SetBoardIdx(int, int); void set_level(int); void set_game_mode(int); };
class app { public: static app *inst(); game *get_game(); };
enum { GAME_MODE_CAREER = 1 };
struct FEManager { void *IGO; void *pms; GraphicalMenuSystem *gms; void *em; int current_surfer; };
extern FEManager frontendmanager;

class DemoModeManager
{
private:
    float totalTime;
    float timeoutDelay;
    float demoDuration;
    float demoTime;
    bool inDemo;
    bool played;
    bool demoStarted;
    char fname[24];
    bool wasInTitle;
public:
    unsigned int replayFrames;
    unsigned int replayMainPOFrames;
    unsigned int replayAIPOFrames;
    char replay_layout_context[0x20];
    nglFileBuf replayFile;
    void GoGame();
};

// Enter the game
void DemoModeManager::GoGame()
{
	// Setup state
	os_file peek;
	bool worked = 0;
	int searchCount = 0;
	// Generate the name
	int replay = random(NUMBER_OF_REPLAYS);
	sprintf(fname, "DEMOS\\REPLAY%d.RPL", replay);
	if (	frontendmanager.gms->active == GraphicalMenuSystem::TitleMenu )
		wasInTitle = true;
	else
		wasInTitle = false;
	// Try to open this one.  
	// Start searching for a good copy.
	while ((!worked) && (searchCount < NUMBER_OF_REPLAYS))
	{
		if (os_file::file_exists(fname))
		{
      int i;

			int	surferIdx;
			int	boardIdx;
			int	beachIdx;
      char beachName[32];

			stringx tmp;

      // Disable the stash only flag if set (since demo files are not in stashes)
      bool stashOnly = os_developer_options::inst()->is_flagged(os_developer_options::FLAG_STASH_ONLY);
      os_developer_options::inst()->set_flag(os_developer_options::FLAG_STASH_ONLY, false);

      KSReadFile(fname, &replayFile, 1);

      surferIdx = *((int *)(&replayFile.Buf[0]));
      boardIdx  = *((int *)(&replayFile.Buf[4]));
      strcpy(beachName, (char *)(&replayFile.Buf[8]));

      // Find the beach index from the name
      int numEntries = sizeof(CareerDataArray) / sizeof(CareerDataArray[0]);
      for(i=0; i<numEntries; i++)
      {
        if(0 == strcmp(beachName, CareerDataArray[i].name))
          break;
      }

      if(i == numEntries)
        assert(0 && "Beach file not found");

      beachIdx = i;

      int offset = 4 + 4 + 32 + sizeof(KSWaterState);
      replayFrames        = *((int *)(&replayFile.Buf[offset]));
      replayMainPOFrames  = *((int *)(&replayFile.Buf[offset+4]));
      replayAIPOFrames    = *((int *)(&replayFile.Buf[offset+8]));

      // Must release here and read a second time after the level is loaded (or there's a mem leak)
      KSReleaseFile(&replayFile);
      os_developer_options::inst()->set_flag(os_developer_options::FLAG_STASH_ONLY, stashOnly);

			frontendmanager.current_surfer = ksreplay.sfr;
			tmp = SurferDataArray[surferIdx].name;
			app::inst()->get_game()->setHeroname(0, tmp);
			app::inst()->get_game()->SetSurferIdx(0, surferIdx);
			app::inst()->get_game()->SetBoardIdx(0, boardIdx);
			((BeachFrontEnd *)frontendmanager.gms->menus[GraphicalMenuSystem::BeachMenu])->PickDemo(ksreplay.bch);
			app::inst()->get_game()->set_level(beachIdx);
			app::inst()->get_game()->set_game_mode(GAME_MODE_CAREER);
			//((BeachFrontEnd *)frontendmanager.gms->menus[GraphicalMenuSystem::BeachMenu])->Select(ksreplay.bch);
			//frontendmanager.map_loading_screen = true;
			frontendmanager.gms->PrepareToExit();
			worked = 1;
		}
		else
		{
			// Keep looking
			searchCount++;
			replay++;
			if (replay == NUMBER_OF_REPLAYS)
				replay = 0;
			sprintf(fname, "DEMOS\\REPLAY%d.RPL", replay);
		}
	}

	// Search failed.
	if (!worked)
	{
		inDemo = false;
		demoStarted = false;
		totalTime = 0;
		return;
	}

	// Go to it
	//g_game_ptr->unpause();
	//g_game_ptr->go_next_state();
	//frontendmanager.gms->Exit();
}
